package com.mycompany.sistemacontable.vista;
import com.mycompany.sistemacontable.servicio.ConciliacionService; import com.mycompany.sistemacontable.modelo.MovimientoBancario; import javax.swing.*; import javax.swing.table.DefaultTableModel; import java.awt.*; import java.io.File;
public class PanelConciliacion extends JPanel {private final ConciliacionService s=new ConciliacionService();private final DefaultTableModel m=new DefaultTableModel(new Object[]{"ID","Fecha","Descripción","Monto","Estado","Puntaje","Asiento sugerido"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable t=new JTable(m);public PanelConciliacion(){setLayout(new BorderLayout(10,10));setBorder(BorderFactory.createEmptyBorder(25,30,30,30));JPanel top=new JPanel(new FlowLayout(FlowLayout.LEFT));JLabel title=new JLabel("Conciliación bancaria asistida");title.setFont(new Font("Segoe UI",Font.BOLD,26));JButton imp=new JButton("Cargar Excel/CSV");JButton ok=new JButton("Marcar conciliado");JButton no=new JButton("Descartar sugerencia");top.add(title);top.add(imp);top.add(ok);top.add(no);add(top,BorderLayout.NORTH);add(new JScrollPane(t),BorderLayout.CENTER);imp.addActionListener(e->importar());ok.addActionListener(e->decidir(true));no.addActionListener(e->decidir(false));cargar();}private void importar(){JFileChooser fc=new JFileChooser();if(fc.showOpenDialog(this)==JFileChooser.APPROVE_OPTION)try{int n=s.importar(fc.getSelectedFile());cargar();JOptionPane.showMessageDialog(this,n+" movimientos importados y analizados.");}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Error",0);}}private void decidir(boolean b){int r=t.getSelectedRow();if(r<0)return;try{s.decidir(Long.parseLong(m.getValueAt(r,0).toString()),b);cargar();}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage());}}public void cargar(){m.setRowCount(0);for(MovimientoBancario x:s.listar())m.addRow(new Object[]{x.getIdMovimiento(),x.getFecha(),x.getDescripcion(),x.getMonto(),x.getEstado(),x.getPuntaje()+"%",x.getAsientoSugerido()});}}
